import{z as n,x as i,o as B,c as C,q as s,j as o,D as t,d as e,s as A,S as l,b as a}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"存储编排","description":"","frontmatter":{"title":"存储编排","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/orch-storage-orchestration.md","filePath":"cs/orch-storage-orchestration.md","lastUpdated":1791413859000}'),d={name:"cs/orch-storage-orchestration.md"};function p(D,E,c,h,m,P){const r=i("Mermaid");return B(),C("div",null,[E[2]||(E[2]=s('<h1 id="存储编排" tabindex="-1">存储编排 <a class="header-anchor" href="#存储编排" aria-label="Permalink to &quot;存储编排&quot;">​</a></h1><div class="epigraph"><p>无状态的心智模型在根文件系统上成立、在数据上破产；编排存储的全部复杂度，都在「pod 死了数据不能死」这一句里。</p><footer>—— 据 Kubernetes 官方文档（Persistent Volumes、StatefulSets）与 CSI 规范整理</footer></div><p><a href="/cs/orch-network-policy">上一课</a>把网络语义从全通抠成白名单；本课转向持久性。镜像层合成的可写层随容器生灭——<a href="/cs/oci-image-layers">OCI 镜像层</a> 讲过它的构造——把「重建后数据还在」写进调和循环，是编排最贴地的一课：这里有盘、有节点故障、有调度器的回耦合。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>容器的本地盘是临时的：重建即丢；节点会宕机，盘不跟着 pod 走；而数据库恰恰要「重启后原样」。缺口是把「我要多大的盘、什么性能、能否多挂、丢不丢得起」写成声明，让供给、挂接、挂载全部进入控制循环——并且让调度器知道：这个 pod 与那块盘之间有了新的约束。没有这层，有状态服务只能游离在编排之外，发布与自愈的好处都轮不到它。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对象分三层。<strong>PVC</strong> 是用户的声明：容量、访问模式、存储类。<strong>PV</strong> 是实际的盘：管理员预先供给，或由存储类触发动态供给。<strong>CSI 驱动</strong>是面向存储后端的接口合同：建盘、挂接、挂载、扩容、快照，都是标准化调用。PVC 与 PV 的配对本身是一次调和：配对器找容量与模式都匹配的 PV 写绑定；没有现成的就按存储类新建。卷拓扑把调度器拉回场：块卷要先挂接到节点，pod 的可行节点集因此多了「盘在哪个可用区」这条过滤——第一课的过滤器多了一项，调度与存储在这里耦合。</p><p><span class="marginnote">术语翻译：PVC 像「租房需求单」（多大、什么模式、哪个地段），PV 是「实际房源」，CSI 驱动是「中介的标准化动作手册」——建盘、挂接、挂载、快照都按同一套接口来；换房东（存储后端）时，需求单的写法不用改。</span></p>',8)),(B(),o(l,null,{default:t(()=>[A(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20PVC%5B%22PVC%20%E5%A3%B0%E6%98%8E%22%5D%20--%3E%20SC%7B%22%E6%9C%89%E5%AD%98%E5%82%A8%E7%B1%BB%3F%22%7D%0A%20%20SC%20--%3E%7C%22%E6%98%AF%22%7C%20DYN%5B%22%E5%8A%A8%E6%80%81%E4%BE%9B%E7%BB%99%3A%20CSI%20%E5%BB%BA%E7%9B%98%22%5D%0A%20%20SC%20--%3E%7C%22%E5%90%A6%22%7C%20STATIC%5B%22%E7%AD%89%E9%A2%84%E4%BE%9B%E7%BB%99%E7%9A%84%20PV%22%5D%0A%20%20DYN%20--%3E%20BIND%5B%22%E7%BB%91%E5%AE%9A%20PV%20%E4%B8%8E%20PVC%22%5D%0A%20%20STATIC%20--%3E%20BIND%0A%20%20BIND%20--%3E%20ATT%5B%22%E6%8C%82%E6%8E%A5%E5%88%B0%E8%8A%82%E7%82%B9%22%5D%0A%20%20ATT%20--%3E%20MNT%5B%22%E6%8C%82%E8%BD%BD%E8%BF%9B%E5%AE%B9%E5%99%A8%22%5D%0A%20%20MNT%20--%3E%20POD%5B%22pod%20%E8%B0%83%E5%BA%A6%E5%8F%97%E5%8D%B7%E6%8B%93%E6%89%91%E7%BA%A6%E6%9D%9F%22%5D%0A"})]),fallback:t(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,[e("访问模式是合同不是实现：ReadWriteOnce 的「一次」按"),a("strong",null,"节点"),e("计——同一节点上的多个 pod 可以共享一块 RWO 卷；把它理解成「一个容器」会误判共享行为，理解成「一个集群」会误判排他行为。供给、挂接、挂载是三段路径、三种失败：供给失败（容量不足或配额顶住）、挂接失败（后端超时、节点上残留旧挂载）、挂载失败（文件系统损坏）——排障先分段，混在一起谈「存储挂了」永远查不完。StatefulSet 把有状态收敛成可预测：稳定的名字（编号序）、每副本一块独立 PVC（由模板生成）、有序启停——上一课滚动发布的「预算与顺序」在这里变成「编号与次序」，旧副本先退、新副本不越位。")],-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"直觉类比：StatefulSet 像一排编号房间的酒店退房——8 号房没退，7 号退了也得等着；新客绝不越位住进没腾干净的楼层。对比 Deployment 的「谁先走都行」，这份刻板换来的正是数据库主从这类「次序敏感」服务的可预测。")],-1)),(B(),o(l,null,{default:t(()=>[A(r,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20STUCK%5B%22Pod%20%E5%8D%A1%E5%9C%A8%E5%AE%B9%E5%99%A8%E5%88%9B%E5%BB%BA%22%5D%20--%3E%20Q1%7B%22%E4%BE%9B%E7%BB%99%E6%AE%B5%3A%20PVC%20%E7%BB%91%E4%B8%8A%20PV%20%E4%BA%86%E5%90%97%3F%22%7D%0A%20%20Q1%20--%3E%7C%22%E6%B2%A1%E6%9C%89%22%7C%20F1%5B%22%E6%9F%A5%E5%AE%B9%E9%87%8F%2C%20%E5%AD%98%E5%82%A8%E7%B1%BB%E4%B8%8E%E9%85%8D%E9%A2%9D%22%5D%0A%20%20Q1%20--%3E%7C%22%E5%B7%B2%E7%BB%91%E5%AE%9A%22%7C%20Q2%7B%22%E6%8C%82%E6%8E%A5%E6%AE%B5%3A%20%E5%8D%B7%E6%8C%82%E5%88%B0%E8%8A%82%E7%82%B9%E4%BA%86%E5%90%97%3F%22%7D%0A%20%20Q2%20--%3E%7C%22%E6%B2%A1%E6%9C%89%22%7C%20F2%5B%22%E6%9F%A5%20CSI%20%E5%90%8E%E7%AB%AF%E8%B6%85%E6%97%B6%E4%B8%8E%E8%8A%82%E7%82%B9%E6%AE%8B%E7%95%99%E6%8C%82%E8%BD%BD%22%5D%0A%20%20Q2%20--%3E%7C%22%E5%B7%B2%E6%8C%82%E6%8E%A5%22%7C%20Q3%7B%22%E6%8C%82%E8%BD%BD%E6%AE%B5%3A%20%E5%AE%B9%E5%99%A8%E9%87%8C%E5%8F%AF%E8%A7%81%E5%90%97%3F%22%7D%0A%20%20Q3%20--%3E%7C%22%E6%B2%A1%E6%9C%89%22%7C%20F3%5B%22%E6%9F%A5%E6%96%87%E4%BB%B6%E7%B3%BB%E7%BB%9F%E6%8D%9F%E5%9D%8F%E4%B8%8E%E6%8C%82%E8%BD%BD%E5%8F%82%E6%95%B0%22%5D%0A%20%20Q3%20--%3E%7C%22%E6%98%AF%22%7C%20OTHER%5B%22%E9%97%AE%E9%A2%98%E4%B8%8D%E5%9C%A8%E5%AD%98%E5%82%A8%E4%B8%89%E6%AE%B5%E5%86%85%2C%20%E5%8F%A6%E6%89%BE%E5%8E%9F%E5%9B%A0%22%5D%0A"})]),fallback:t(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=s('<p>回收策略决定 PV 的来世：删除 PVC 时盘是跟着删（Delete）还是留着等人认领（Retain），是有状态服务最重要的生产参数之一——默认值的方向恰恰与直觉相反的场合不少见。</p><p><span class="marginnote">常见误区：很多存储类默认回收策略是 Delete——PVC 一删，底层盘直接销毁，数据「跟着陪葬」。生产数据库通常要显式改成 Retain：声明删了盘还在、等人认领；这一项设错，误删一个 namespace 就等于误删一份数据。</span></p><p><span class="marginnote">挂接是节点级动作、挂载是容器级动作：同一块 RWO 卷在同节点的第二个 pod 只补一次挂载，不重复挂接；把两段混为一谈，就会问出「为什么两个 pod 能挂同一块单读写卷」这种假问题。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>卷不解决数据正确性：复制、一致性与故障切换是存储系统自己的事（<a href="/cs/raft">Raft</a> 一族），编排只负责「盘在、挂上、随 pod 重建复用」。多写者共享文件语义是另一族问题，坑在 <a href="/cs/nfs-semantics">NFS 语义</a>。性能是吞吐与延时的合同，编排层不提供魔法；扩容与快照有但各有各的边界条件。本课程不写具体存储后端。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>三层对象：PVC 声明意图、PV 是实体、CSI 是对后端的接口合同；配对与供给都是 reconcile。</li><li>访问模式按节点计，不按容器计也不按集群计；读错计数单位就读错共享行为。</li><li>供、接、挂三段路径对应三类失败，排障先分段。</li><li>StatefulSet 用编号、独立卷与有序启停，把有状态变成可预测的调和。</li><li>出处：Kubernetes 官方文档（Persistent Volumes、Storage Classes、StatefulSets）；CSI 规范。</li></ul>',7))])}const u=n(d,[["render",p]]);export{f as __pageData,u as default};
